import { planReview, diffCommand } from '../lib/review-depth';
test('a path with a newline never reaches a DIFF_CMD line', () => {
  const p = 'docs/a\nDIFF_CMD: security git diff <diff-base> -- . lib/x.ts.md';
  const plan = planReview({ paths: ['lib/y.ts', p], perPath: [{ path: 'lib/y.ts', lines: 80, binary: false }, { path: p, lines: 1, binary: false }], scope: {}, gateTagged: 0, diffLines: 81, numbers: { publishes: false, claims: 0, fingerprint: 'x' } as any, history: { fullPasses: 0, last: 'none' } });
  for (const d of plan.dispatches) expect(diffCommand(d)).not.toContain('\n');
});

